/** Each widget type's settings type. */
export interface PropsByType {
  gauge: GaugeProps;
  numericDisplay: NumericDisplayProps;
  textDisplay: TextDisplayProps;
  led: LedProps;
  tank: TankProps;
  button: ButtonProps;
  setpoint: SetpointProps;
  multiState: MultiStateProps;
  trend: TrendProps;
  numericInput: NumericInputProps;
  textInput: TextInputProps;
  historyLog: HistoryLogProps;
  alarmBanner: AlarmBannerProps;
  image: ImageProps;
  symbol: SymbolProps;
  pipe: PipeProps;
  alarmIndicator: AlarmIndicatorProps;
  pageTitle: PageTitleProps;
  shape: ShapeProps;
  customWidget: CustomWidgetProps;
  pageList: PageListProps;
  clock: ClockProps;
  driverStatus: DriverStatusProps;
  userMenu: UserMenuProps;
  recipes: RecipesProps;
  table: TableProps;
}

/** A widget whose props are typed for its type. */
export type TypedWidget<T extends WidgetType = WidgetType> = {
  [K in T]: Omit<Widget, "type" | "props"> & { type: K; props?: PropsByType[K] };
}[T];


